'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var strided = require( '@stdlib/blas/ext/base/dcusumkbn' ).ndarray;
var canUseNative = require( './can_use_native.js' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Computes the cumulative sum of a one-dimensional double-precision floating-point ndarray using an improved Kahan–Babuška algorithm.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*     -   a zero-dimensional ndarray containing the initial sum.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var x = new Float64Vector( [ 1.0, 3.0, 4.0, 2.0 ] );
* var y = new Float64Vector( [ 0.0, 0.0, 0.0, 0.0 ] );
*
* var initial = scalar2ndarray( 0.0, {
*     'dtype': 'float64'
* });
*
* var z = dcusumkbn( [ x, y, initial ] );
* // returns <ndarray>[ 1.0, 4.0, 8.0, 10.0 ]
*
* var bool = ( z === y );
* // returns true
*/
function dcusumkbn( arrays ) {
	var xb;
	var sx;
	var ox;
	var yb;
	var sy;
	var oy;
	var x;
	var y;
	var v;
	var N;

	x = arrays[ 0 ];
	y = arrays[ 1 ];
	v = ndarraylike2scalar( arrays[ 2 ] );
	N = numelDimension( x, 0 );
	xb = getData( x );
	sx = getStride( x, 0 );
	ox = getOffset( x );
	yb = getData( y );
	sy = getStride( y, 0 );
	oy = getOffset( y );

	if ( typeof v === 'number' && canUseNative( N, xb, sx, ox ) && canUseNative( N, yb, sy, oy ) ) {
		addon( N, v, xb, sx, ox, yb, sy, oy );
	} else {
		strided( N, v, xb, sx, ox, yb, sy, oy );
	}
	return y;
}


// EXPORTS //

module.exports = dcusumkbn;
